import csv
from typing import Union

def column_means(csv_text: str) -> dict[str, float]:
    """
    Calculate the mean of each numeric column in a CSV string.

    Args:
        csv_text: A string containing CSV data with a header row.

    Returns:
        A dictionary mapping column names to their mean values.
        Columns are skipped if they contain non-numeric values or have no valid numbers.
    """
    reader = csv.reader(csv_text.splitlines())

    try:
        headers = next(reader)
    except StopIteration:
        return {}

    # Initialize storage for column sums and counts
    column_data: dict[str, list[Union[float, None]]] = {header: [] for header in headers}

    for row in reader:
        if len(row) != len(headers):
            continue

        for i, value in enumerate(row):
            header = headers[i]
            if not value.strip():
                continue

            try:
                num_value = float(value)
                column_data[header].append(num_value)
            except ValueError:
                # If any value is non-numeric, we will skip this column later
                pass

    result = {}
    for header, values in column_data.items():
        if not values:
            continue

        # Check if all collected values are valid (they should be by construction)
        # Calculate mean
        mean_value = sum(values) / len(values)
        result[header] = mean_value

    return result
