import socket
import threading
from typing import Optional, Set

class ChatServer:
    def __init__(self, host: str = "127.0.0.1", port: int = 0):
        self.host = host
        self.port = port
        self._server_socket: Optional[socket.socket] = None
        self._clients: dict[str, socket.socket] = {}  # username -> socket
        self._lock = threading.Lock()
        self._is_running = False

    def start(self) -> int:
        """Start the server in a background thread and return the bound port."""
        if self.port == 0:
            # Find an available port
            with socket.socket(socket.AF_INET, socket.SOCK_STREAM) as temp_sock:
                temp_sock.bind((self.host, 0))
                temp_sock.listen(1)
                self.port = temp_sock.getsockname()[1]

        self._server_socket = socket.socket(socket.AF_INET, socket.SOCK_STREAM)
        self._server_socket.setsockopt(socket.SOL_SOCKET, socket.SO_REUSEADDR, 1)
        self._server_socket.bind((self.host, self.port))
        self._server_socket.listen(5)

        self._is_running = True

        def run_server():
            while self._is_running:
                try:
                    conn_addr, _ = self._server_socket.accept()
                    thread = threading.Thread(target=self._handle_client, args=(conn_addr,), daemon=True)
                    thread.start()
                except socket.error:
                    if self._is_running:
                        break

        thread = threading.Thread(target=run_server, daemon=True)
        thread.start()
        return self.port

    def stop(self):
        """Shut down the server."""
        self._is_running = False
        if self._server_socket:
            try:
                self._server_socket.close()
            except socket.error:
                pass

        # Close all client sockets to ensure clean shutdown
        with self._lock:
            for sock in self._clients.values():
                try:
                    sock.close()
                except socket.error:
                    pass

    def _handle_client(self, conn: socket.socket):
        """Handle a single client connection."""
        username = None

        try:
            # Read first line (registration)
            data = b""
            while True:
                chunk = conn.recv(4096)
                if not chunk:
                    break
                data += chunk
                if b"\n" in data:
                    break

            if not data:
                return

            line = data.decode("utf-8").strip()

            # Check for registration format "NAME <username>"
            if line.startswith("NAME "):
                username = line[5:]  # Extract username after "NAME "

                with self._lock:
                    if username in self._clients:
                        # Name taken, close connection immediately
                        conn.close()
                        return

                    # Register client
                    self._clients[username] = conn

                # Notify others of join
                self._broadcast(f"* {username} joined\n", exclude=username)

            else:
                # Not a registration line (or malformed), close connection
                conn.close()
                return

        except Exception:
            try:
                with self._lock:
                    if username and username in self._clients:
                        del self._clients[username]
            except KeyError:
                pass

        finally:
            # Handle disconnect notification if we have a valid username registered
            if username and username in self._clients:
                try:
                    conn.close()
                    with self._lock:
                        del self._clients[username]
                    self._broadcast(f"* {username} left\n", exclude=username)
                except socket.error:
                    pass

    def _broadcast(self, message: str, exclude: Optional[str] = None):
        """Send a message to all connected clients except the specified one."""
        if not self._clients:
            return

        with self._lock:
            # Create a list of sockets to iterate over safely
            sockets_to_send = list(self._clients.values())

        for sock in sockets_to_send:
            try:
                if exclude is None or sock != self._clients[exclude]:
                    sock.sendall(message.encode("utf-8"))
            except socket.error:
                # Client disconnected, will be cleaned up by the main loop or next recv
                pass
