import re
from typing import Callable, Dict, Tuple, Any

class NotFound(Exception):
    """Raised when no route matches the given path."""
    pass

class MethodNotAllowed(Exception):
    """Raised when a route matches the path but not the HTTP method."""
    pass

class Router:
    def __init__(self):
        # Store routes as (method, pattern, handler)
        self.routes: list = []

    def add(self, method: str, pattern: str, handler: Callable) -> None:
        """
        Registers a route.
        Patterns look like '/users/{id}/posts'.
        A '{name}' segment matches exactly one non-empty path segment.
        """
        self.routes.append((method, pattern, handler))

    def _normalize_path(self, path: str) -> str:
        """Remove trailing slash if present, unless the path is just '/'. """
        if path == "/":
            return path
        return path.rstrip('/')

    def _compile_pattern(self, pattern: str) -> Tuple[str, re.Pattern]:
        """
        Converts a pattern string like '/users/{id}/posts' into a regex.
        Returns the original pattern and the compiled regex.
        """
        # Normalize pattern (remove trailing slash for consistency with dispatch logic)
        norm_pattern = self._normalize_path(pattern)

        # Escape special regex characters except '{' and '}'
        escaped = re.escape(norm_pattern)

        # Replace {name} with a capturing group for non-empty segments
        # We use [^/]+ to match one or more characters that are not '/'
        regex = re.sub(r'\{[^}]+\}', r'([^/]+)', escaped)

        return norm_pattern, re.compile(f"^{regex}$")

    def _match_static_routes(self, path: str, method: str) -> Tuple[bool, Callable, Dict[str, str]]:
        """
        Checks if any static route (no parameters) matches the path and method.
        Returns (matched, handler, params). If matched is False, returns (False, None, {}).
        """
        for m, p, h in self.routes:
            # Check method first
            if m != method:
                continue

            # Check if pattern has parameters
            if '{' in p:
                continue

            # Static route match check
            if path == p:
                return True, h, {}

        return False, None, {}

    def _match_param_routes(self, path: str, method: str) -> Tuple[bool, Callable, Dict[str, str]]:
        """
        Checks if any parameterized route matches the path and method.
        Static routes are handled separately to ensure they win.
        """
        compiled_patterns = {}

        # Pre-compile all param patterns once per dispatch call for efficiency
        for m, p, h in self.routes:
            if '{' not in p:
                continue

            if m not in compiled_patterns:
                compiled_patterns[m] = []

            norm_p, regex = self._compile_pattern(p)
            compiled_patterns[m].append((norm_p, regex, h))

        # Try to match against pre-compiled patterns
        for m, pattern_list in compiled_patterns.items():
            if m != method:
                continue

            for norm_p, regex, h in pattern_list:
                match = regex.match(path)
                if match:
                    # Extract groups. The regex adds a leading '^' and trailing '$'.
                    # Groups are 1-indexed in the match object.
                    params = dict(zip(regex.groupindex.keys(), match.groups()))
                    return True, h, params

        return False, None, {}

    def dispatch(self, method: str, path: str) -> Tuple[Callable, Dict[str, str]]:
        """
        Dispatches a request to the appropriate handler.
        Returns (handler, params).
        Raises NotFound if no route matches the path.
        Raises MethodNotAllowed if a route matches the path but not the method.
        """
        norm_path = self._normalize_path(path)

        # 1. Check for static route match first (highest priority)
        matched_static, handler, params = self._match_static_routes(norm_path, method)
        if matched_static:
            return handler, params

        # 2. Check for parameterized route match
        matched_param, handler, params = self._match_param_routes(norm_path, method)
        if matched_param:
            return handler, params

        # 3. Determine exception
        # We need to know if ANY route matches the path regardless of method to decide between 
        # NotFound and MethodNotAllowed.

        # Check if any route (static or param) matches the path ignoring method
        any_match = False
        for m, p, h in self.routes:
            norm_p, regex = self._compile_pattern(p)
            match = regex.match(norm_path)
            if match:
                any_match = True
                break

        if not any_match:
            raise NotFound("No route matches the given path.")
        else:
            # A route exists for this path, but the method didn't match.
            raise MethodNotAllowed(f"Method {method} is not allowed for the given path.")
